/**
 * modules/school/mgmt.js — Management + Facilities & Services API.
 *
 * Mounted INSIDE the school router (router.use("/mgmt", mgmtRouter)) so the
 * audit-trail middleware in routes.js covers every write here too.
 * All data lives in the `mgmt` schema; every row is scoped by school_id.
 *
 * Most endpoints are generated by a small CRUD factory keyed by RESOURCES:
 *   GET    /api/school/mgmt/:resource          list (whitelisted ?field= filters)
 *   POST   /api/school/mgmt/:resource          create
 *   PUT    /api/school/mgmt/:resource/:id      update
 *   DELETE /api/school/mgmt/:resource/:id      delete
 * Custom routes (dashboards, attendance register, fee collection, promote,
 * due slips, carry-forward) are registered BEFORE the generic ones.
 */

