// Render a saved template filled with values; optionally save a record.
// Body: { data, title?, student_id?, staff_id?, save? }
router.post("/document-templates/:id/render", authenticateToken, requireRole(SCHOOL_ROLES), async (req, res) => {
  try {
    const school = await getMySchool(req, res);
    if (!school) return;
    // Load from the school's template or the shared default gallery.
    let tpl;
    if (String(req.params.id).startsWith("default:")) tpl = getDefaultDoc(String(req.params.id).slice("default:".length));
    else ({ data: tpl } = await M().from("document_templates").select("*").eq("id", req.params.id).eq("school_id", school.id).maybeSingle());
    if (!tpl) return res.status(404).json({ error: "Template not found" });
    const values = req.body.data || {};
    const html = renderDocument({ body: tpl.body, css: tpl.css, pageSize: tpl.page_size, orientation: tpl.orientation, data: values });

    let record = null;
    if (req.body.save) {
      const templateId = await ensureSchoolDocTemplate(school, req.params.id); // clone default if needed
      const serial = `DOC-${Date.now().toString(36).toUpperCase()}`;
      const { data: rec, error } = await M().from("document_records").insert({
        school_id: school.id, template_id: templateId || null, title: req.body.title || tpl.name,
        serial_no: serial, data: values, student_id: req.body.student_id || null, staff_id: req.body.staff_id || null,
      }).select("*").single();
      if (error) throw new Error(error.message);
      record = rec;
    }
    res.json({ success: true, html, record });
  } catch (e) { res.status(500).json({ error: e.message }); }
});

// A saved record rendered as a standalone print-ready page (open/print).
router.get("/document-records/:id/html", authenticateToken, async (req, res) => {
  try {
    const school = await getMySchool(req, res);
    if (!school) return;
    const { data: rec } = await M().from("document_records").select("*").eq("id", req.params.id).eq("school_id", school.id).maybeSingle();
    if (!rec) return res.status(404).type("html").send("<h1>Document not found</h1>");
    const { data: tpl } = rec.template_id
      ? await M().from("document_templates").select("*").eq("id", rec.template_id).maybeSingle()
      : { data: null };
    const html = renderDocument({ body: tpl?.body || "", css: tpl?.css, pageSize: tpl?.page_size, orientation: tpl?.orientation, data: rec.data || {} });
    res.type("html").send(html);
  } catch (e) { res.status(500).type("html").send("<h1>Something went wrong</h1>"); }
});

// ── Admission wizard: suggest the next admission number + roll number ──────
// GET /students/next-codes?class_id=  → { admission_no, roll_no }
// admission_no = (max integer found in any existing admission_no) + 1.
// roll_no      = (max roll within the class, or overall) + 1.
router.get("/students/next-codes", authenticateToken, async (req, res) => {
  try {
    const school = await getMySchool(req, res);
    if (!school) return;
    const { data: rows } = await M().from("students")
      .select("admission_no, roll_no, class_id").eq("school_id", school.id);
    const all = rows || [];
    const maxAdm = all.reduce((max, r) => {
      const n = parseInt(String(r.admission_no || "").replace(/\D/g, ""), 10);
      return Number.isFinite(n) && n > max ? n : max;
    }, 0);
    const classId = req.query.class_id || null;
    const rollPool = classId ? all.filter((r) => r.class_id === classId) : all;
    const maxRoll = rollPool.reduce((max, r) => {
      const n = parseInt(String(r.roll_no || "").replace(/\D/g, ""), 10);
      return Number.isFinite(n) && n > max ? n : max;
    }, 0);
    res.json({ success: true, data: { admission_no: String(maxAdm + 1), roll_no: String(maxRoll + 1) } });
  } catch (e) { res.status(500).json({ error: e.message }); }
});

// ── Admission wizard: assign fee groups (+ optional opening balance) ───────
// POST /students/:id/assign-fee-groups  { group_ids: [], opening_balance }
// Creates one fee_assignment per fee_type in each selected group (at the
// type's default_amount), scoped to the active session. An opening balance
// is recorded against a find-or-created "Opening Due Balance" fee type.
router.post("/students/:id/assign-fee-groups", authenticateToken, requireRole(SCHOOL_ROLES), async (req, res) => {
  try {
    const school = await getMySchool(req, res);
    if (!school) return;
    const { data: student } = await M().from("students").select("id").eq("id", req.params.id).eq("school_id", school.id).maybeSingle();
    if (!student) return res.status(404).json({ error: "Student not found" });

    const groupIds = Array.isArray(req.body.group_ids) ? req.body.group_ids : [];
    const openingBalance = Number(req.body.opening_balance) || 0;
    const { data: session } = await M().from("academic_sessions").select("id").eq("school_id", school.id).eq("is_active", true).maybeSingle();
    const sessionId = session?.id || null;

    const rows = [];
    if (groupIds.length) {
      const { data: types } = await M().from("fee_types").select("id, default_amount, group_id").eq("school_id", school.id).in("group_id", groupIds);
      for (const t of types || []) rows.push({ school_id: school.id, student_id: student.id, fee_type_id: t.id, amount: Number(t.default_amount) || 0, session_id: sessionId });
    }
    if (openingBalance > 0) {
      let { data: obType } = await M().from("fee_types").select("id").eq("school_id", school.id).eq("name", "Opening Due Balance").maybeSingle();
      if (!obType) {
        const { data: created, error: ctErr } = await M().from("fee_types").insert({ school_id: school.id, name: "Opening Due Balance" }).select("id").single();
        if (ctErr) throw new Error(ctErr.message);
        obType = created;
      }
      rows.push({ school_id: school.id, student_id: student.id, fee_type_id: obType.id, amount: openingBalance, session_id: sessionId });
    }

    let assigned = 0;
    if (rows.length) {
      const { error } = await M().from("fee_assignments").insert(rows);
      if (error) throw new Error(error.message);
      assigned = rows.length;
    }
    res.json({ success: true, assigned });
  } catch (e) { res.status(500).json({ error: e.message }); }
});

// ── Load a starter timetable template into a class ────────────────────────
// Body: { class_id, section_id?, variant?: 'junior'|'senior', replace?: bool }
// Seeds the 14 periods + subjects (if missing) and fills the class grid.
// Without replace, refuses (409) if the class already has slots.
router.post("/timetable/load-template", authenticateToken, requireRole(SCHOOL_ROLES), async (req, res) => {
  try {
    const school = await getMySchool(req, res);
    if (!school) return;
    const { class_id, section_id = null, replace = false } = req.body;
    if (!class_id) return res.status(400).json({ error: "class_id is required" });

    // Choose grid: explicit variant, else infer from class name (JSS→junior).
    const { data: cls } = await M().from("classes").select("name").eq("id", class_id).eq("school_id", school.id).maybeSingle();
    if (!cls) return res.status(404).json({ error: "Class not found" });
    const variant = req.body.variant || (/^(jss|grade|primary|basic|junior)/i.test(cls.name) ? "junior" : "senior");
    const grid = variant === "senior" ? SENIOR_GRID : JUNIOR_GRID;

    // Existing slots guard.
    let sq = M().from("timetable_slots").select("id").eq("school_id", school.id).eq("class_id", class_id);
    sq = section_id ? sq.eq("section_id", section_id) : sq.is("section_id", null);
    const { data: existing } = await sq;
    if (existing?.length && !replace) {
      return res.status(409).json({ error: "This class already has a timetable.", code: "exists", count: existing.length });
    }
    if (existing?.length && replace) {
      let dq = M().from("timetable_slots").delete().eq("school_id", school.id).eq("class_id", class_id);
      dq = section_id ? dq.eq("section_id", section_id) : dq.is("section_id", null);
      await dq;
    }

    // Ensure subjects (by code) and map code → id.
    const codes = TEMPLATE_SUBJECTS.map((s) => s[1]);
    let { data: subs } = await M().from("subjects").select("id, code").eq("school_id", school.id).in("code", codes);
    const have = new Set((subs || []).map((s) => s.code));
    const toAdd = TEMPLATE_SUBJECTS.filter((s) => !have.has(s[1])).map(([name, code, type]) => ({ school_id: school.id, name, code, subject_type: type }));
    if (toAdd.length) { await M().from("subjects").insert(toAdd); ({ data: subs } = await M().from("subjects").select("id, code").eq("school_id", school.id).in("code", codes)); }
    const subjIdByCode = Object.fromEntries((subs || []).map((s) => [s.code, s.id]));

    // Ensure the 14 periods (by name) and map name → id.
    let { data: pers } = await M().from("periods").select("id, name").eq("school_id", school.id).in("name", PERIOD_DEFS.map((p) => p.name));
    const havePer = new Set((pers || []).map((p) => p.name));
    const addPer = PERIOD_DEFS.filter((p) => !havePer.has(p.name)).map((p) => ({ school_id: school.id, ...p }));
    if (addPer.length) { await M().from("periods").insert(addPer); ({ data: pers } = await M().from("periods").select("id, name").eq("school_id", school.id).in("name", PERIOD_DEFS.map((p) => p.name))); }
    const perIdByName = Object.fromEntries((pers || []).map((p) => [p.name, p.id]));

    // Build the slot rows from the grid.
    const rows = [];
    grid.forEach((day, di) => {
      day.forEach((cell, ci) => {
        const [code, alt] = Array.isArray(cell) ? cell : [cell, null];
        const period_id = perIdByName[TEACH_PERIOD_NAMES[ci]];
        const subject_id = subjIdByCode[code];
        if (!period_id || !subject_id) return;
        rows.push({ school_id: school.id, class_id, section_id, day_of_week: di + 1, period_id, subject_id, alt_subject_id: alt ? (subjIdByCode[alt] || null) : null });
      });
    });
    if (rows.length) {
      const { error } = await M().from("timetable_slots").insert(rows);
      if (error) throw new Error(error.message);
    }

    res.json({ success: true, variant, created: rows.length });
  } catch (e) { res.status(500).json({ error: e.message }); }
});

/* ═══════════════════════ Generic CRUD ════════════════════════════════════ */

router.get("/:resource", authenticateToken, async (req, res) => {
  try {
    const cfg = RESOURCES[req.params.resource];
    if (!cfg) return res.status(404).json({ error: "Unknown resource" });
    const school = await getMySchool(req, res);
    if (!school) return;
    let q = M().from(cfg.table).select("*").eq("school_id", school.id)
      .order(cfg.orderBy || "created_at", { ascending: cfg.asc ?? false }).limit(500);
    for (const f of cfg.filters || []) {
      if (req.query[f] === undefined || req.query[f] === "") continue;
      // "__null__" filters for rows with no value (e.g. students without a class)
      q = req.query[f] === "__null__" ? q.is(f, null) : q.eq(f, req.query[f]);
    }
    const { data, error } = await q;
    if (error) throw new Error(error.message);
    res.json({ success: true, data: await attachRefs(cfg, data || [], school.id) });
  } catch (e) { res.status(500).json({ error: e.message }); }
});

router.post("/:resource", authenticateToken, requireRole(SCHOOL_ROLES), async (req, res) => {
  try {
    const cfg = RESOURCES[req.params.resource];
    if (!cfg || cfg.readOnly || cfg.readOnlyCreate) return res.status(404).json({ error: "Unknown resource" });
    const school = await getMySchool(req, res);
    if (!school) return;
    const body = cleanBody(cfg, req.body);
    for (const f of cfg.required || []) {
      if (body[f] === undefined || body[f] === null || body[f] === "") return res.status(400).json({ error: `${f} is required` });
    }
    const { data, error } = await M().from(cfg.table).insert({ ...body, school_id: school.id }).select("*").single();
    if (error) {
      if (error.code === "23505") return res.status(409).json({ error: "A record with those unique values already exists" });
      throw new Error(error.message);
    }
    res.status(201).json({ success: true, data: (await attachRefs(cfg, [data], school.id))[0] });
  } catch (e) { res.status(500).json({ error: e.message }); }
});

router.put("/:resource/:id", authenticateToken, requireRole(SCHOOL_ROLES), async (req, res) => {
  try {
    const cfg = RESOURCES[req.params.resource];
    if (!cfg || cfg.readOnly) return res.status(404).json({ error: "Unknown resource" });
    const school = await getMySchool(req, res);
    if (!school) return;
    const body = cleanBody(cfg, req.body);
    if (!Object.keys(body).length) return res.status(400).json({ error: "No valid fields to update" });
    const { data, error } = await M().from(cfg.table).update(body)
      .eq("id", req.params.id).eq("school_id", school.id).select("*").single();
    if (error) {
      if (error.code === "23505") return res.status(409).json({ error: "A record with those unique values already exists" });
      throw new Error(error.message);
    }
    res.json({ success: true, data: (await attachRefs(cfg, [data], school.id))[0] });
  } catch (e) { res.status(500).json({ error: e.message }); }
});

router.delete("/:resource/:id", authenticateToken, requireRole(SCHOOL_ROLES), async (req, res) => {
  try {
    const cfg = RESOURCES[req.params.resource];
    if (!cfg) return res.status(404).json({ error: "Unknown resource" });
    const school = await getMySchool(req, res);
    if (!school) return;
    const { error } = await M().from(cfg.table).delete().eq("id", req.params.id).eq("school_id", school.id);
    if (error) throw new Error(error.message);
    res.json({ success: true });
  } catch (e) { res.status(500).json({ error: e.message }); }
});

export default router;
